import type { Metadata } from "next";
import { messages } from "@/lib/i18n";

type OpenGraph = NonNullable<Metadata["openGraph"]>;

/**
 * Next.js replaces (does not merge) a parent's openGraph/twitter objects when a page sets its own,
 * so every page builds them from these shared defaults. The image generated by
 * app/opengraph-image.tsx is only attached automatically at the root, so it is referenced here too.
 */
const shareImage = { url: "/opengraph-image", width: 1200, height: 630, alt: messages.meta.siteName };

export function pageOpenGraph(title: string = messages.meta.defaultTitle, description: string = messages.meta.description): OpenGraph {
  return { type: "website", locale: "bn_BD", siteName: messages.meta.siteName, title, description, images: [shareImage] };
}

export function pageTwitter(title: string = messages.meta.defaultTitle, description: string = messages.meta.description): Metadata["twitter"] {
  return { card: "summary_large_image", title, description, images: [shareImage] };
}
